      b: `<div class="dfiles">${x.files.map((f, fi) => `<div class="dfile${D.view === fi ? ' on' : ''}" data-dr-view="${fi}" role="button" tabindex="0"><span class="ft" style="background:var(--tone-${f.t === 'pdf' ? 'red' : 'blue'}-tint);color:var(--tone-${f.t === 'pdf' ? 'red' : 'blue'}-solid)"><i class="ti ti-${f.t === 'pdf' ? 'file-type-pdf' : 'photo'}"></i></span><div><b>${f.n}</b><small>${f.t === 'pdf' ? L('PDF', 'PDF') + ' · ' + (fi ? 4 : 12) + ' ' + L('pages', 'صفحات') : L('Image', 'صورة')} · ${f.s}</small></div><button class="dbtn ter ic dvb" data-dr-view="${fi}" aria-label="${L('View in app', 'عرض داخل التطبيق')}" title="${L('View in app', 'عرض داخل التطبيق')}"><i class="ti ti-eye"></i></button><button class="dbtn ter ic" data-dr-max="${fi}" aria-label="${L('Open large', 'فتح بحجم كبير')}" title="${L('Open large', 'فتح بحجم كبير')}"><i class="ti ti-external-link"></i></button><button class="dbtn ter ic" data-dr-toast="dl" aria-label="${L('Download', 'تنزيل')}"><i class="ti ti-download"></i></button></div>${D.view === fi ? inlineV(f, fi, x) : ''}`).join('')}</div>`
