      pending: [['code', 'ti-gavel', L('Issue code', 'إصدار الرمز'), 1], ['cmt', 'ti-message-circle', L('Comment', 'تعليق')]],
      resub: [['code', 'ti-gavel', L('Issue code', 'إصدار الرمز'), 1], ['cmt', 'ti-message-circle', L('Comment', 'تعليق')]],
      approved: [['pdf', 'ti-file-download', L('Download PDF', 'تنزيل PDF'), 1]],
