    if (V.tab === 'det') body = `${partiesStrip()}<div class="dg2"><div class="dgl">${body}</div><div class="dgr">${statusCard(it)}<section class="boxs"><h6 class="h6y">${L('Approvals Log', 'سجل الاعتمادات')}</h6>${apLog(it)}</section></div></div>`;
