    const chain = it.type === 'SAR' ? `<div class="rch2"><button class="${!V.rev1 || V.it.rev === 0 ? 'on' : ''}" data-chain="0">Rev 0 ${code('C')}</button>${V.rev1 ? `<i class="ti ti-chevron-right"></i><button data-chain="1">Rev 1 · ${L('Draft', 'مسودة')}</button>` : ''}</div>` : '';
    const cre = it.log.find(e => e.a === 'create');
    const main = `<div class="sdh"><div class="sdt2"><div style="flex:1;min-width:0"><h2>${esc(it.title)}</h2><div class="sub2">${numTxt(it)}<i class="dot"></i><span>${L('Created by', 'أنشأه')} <b>${nm(cre ? cre.by : me())}</b> ${L('on', 'في')} <span class="num">${cre ? cre.at.split(' ')[0] : dt().split(' ')[0]}</span></span></div><div class="sdt"><span class="ty" style="background:var(--tone-${ty[4]}-tint);color:var(--tone-${ty[4]}-fg)"><i class="ti ${ty[3]}"></i>${it.type}</span>${stagePill(it)}${it.code ? code(it.code) : ''}${it.stage !== 'closed' && it.stage !== 'cancelled' ? age(it.wk) : ''}${chain}</div></div><div class="sdr"><span class="rolep">${pos(me())}</span><button class="cb sm${V.tab === 'wf' ? ' on' : ''}" data-tab="wf"><i class="ti ti-git-branch"></i>${L('View workflow', 'عرض سير العمل')}</button></div></div>${it.wf === 2 && it.stage !== 'closed' && it.stage !== 'draft' ? `<div class="okb" style="background:var(--tone-blue-tint);color:var(--tone-blue-fg);font-weight:500"><i class="ti ti-info-circle"></i>${L('This item follows v2. The workflow was updated to v3.', 'يتبع هذا العنصر v2. تم تحديث سير العمل إلى v3.')}</div>` : ''}<div class="dtabs">${tabs.map(t => `<button class="${V.tab === t[0] ? 'on' : ''}" data-tab="${t[0]}">${t[1]}${t[2] ? `<span class="bdg">${t[2]}</span>` : ''}</button>`).join('')}</div></div><div class="sdb" id="sfbody">${body}</div>`;
    const bar = acts.length ? `<footer class="sff2 abar">${acts.filter(a => a === 'cancel').map(a => btn(a)).join('')}<span style="flex:1"></span>${acts.filter(a => a !== 'cancel').map(a => btn(a)).join('')}</footer>` : `<footer class="sff2 abar"><span class="hint2"><i class="ti ti-eye"></i>${L('No actions for you at this step.', 'لا إجراءات لك في هذه الخطوة.')}</span></footer>`;
    const top = `<header class="sfh sm"><span class="num" style="opacity:.8">${L('Submittal', 'التقديم')}</span><span style="flex:1"></span><span class="rsel"><i class="ti ti-eye"></i>${L('View as', 'العرض بصفة')}<select id="sfview">${Object.entries(VW).map(([k, p]) => `<option value="${k}"${V.viewer === k ? ' selected' : ''}>${pos(p)} · ${nm(p).split(' ')[0]}</option>`).join('')}</select></span><span class="rsel"><i class="ti ti-player-play"></i><select id="sfdemo">${[['internal', L('Internal Review', 'مراجعة داخلية')], ['pool', L('Pending · pool', 'بانتظار · مجموعة')], ['mgr', L('Pending · manager', 'بانتظار · المدير')], ['B', L('Closed · Code B', 'مغلق · Code B')], ['C', L('Closed · Code C (SAR-007)', 'مغلق · Code C')]].map(o => `<option value="${o[0]}"${V.demo === o[0] ? ' selected' : ''}>${o[1]}</option>`).join('')}</select></span><span class="segv sm2"><button class="${V.phone ? '' : 'on'}" data-ph="0"><i class="ti ti-device-desktop"></i></button><button class="${V.phone ? 'on' : ''}" data-ph="1"><i class="ti ti-device-mobile"></i></button></span><button class="cb ter ic x" data-x="drawer"><i class="ti ti-x"></i></button></header>`;
    if (V.phone) return `<div class="sfscrim" data-x="drawer"><aside class="sfd wide" data-stop>${top}<div class="phwrap"><div class="phone"><div class="scr" style="background:var(--ui-canvas)"><div class="notch"></div><div class="ph2b" id="sfbody"><div class="sdh" style="padding:52px 14px 10px"><div class="sdt">${numTxt(it)}${it.code ? code(it.code) : ''}</div><h2 style="font-size:18px">${esc(it.title)}</h2><div class="sdt">${stagePill(it)}${it.stage !== 'closed' ? age(it.wk) : ''}</div></div><div style="padding:0 12px 120px;display:flex;flex-direction:column;gap:10px"><section class="boxs"><div class="with"><span>${L('With', 'لدى')}</span>${withTxt(it)}</div></section><span class="segv" style="display:flex">${tabs.slice(0, 3).map(t => `<button class="${V.tab === t[0] ? 'on' : ''}" data-tab="${t[0]}" style="flex:1;justify-content:center">${t[1].split(' ')[0]}</button>`).join('')}</span>${V.tab === 'det' ? sections(it, true) : V.tab === 'chat' ? msgs(it.chat, 'chat') : audit(it)}</div></div>${acts.length ? `<button class="phact" data-act="sheet"><i class="ti ti-bolt"></i>${L('Actions', 'الإجراءات')} · ${acts.length}</button>` : ''}${V.sheet ? `<div class="phsh-s" data-act="sheet"></div><div class="phsh">${acts.map(a => btn(a, 1)).join('')}</div>` : ''}${V.pop ? `<div class="phpop">${popup(1)}</div>` : ''}${V.sign ? `<div class="phpop">${signDlg(1)}</div>` : ''}<div class="m-home"></div></div></div></div></aside></div>`;
